/**
 * Sprite – plays one animation row of the pixel-art mascot sprite sheet.
 *
 * The sheet and its frame metadata are generated by scripts/sprites/build-sprites.mjs.
 * Frames are stepped with a CSS `steps()` animation, so there is no JS timer per sprite.
 */
import type { CSSProperties } from 'react';
import sheetUrl from '../../assets/sprites/mascot.png';
import {
  SPRITE_ANIMS,
  SPRITE_COLS,
  SPRITE_FRAME_H,
  SPRITE_FRAME_W,
  SPRITE_ROWS,
  type SpriteAnim,
} from '../../assets/sprites/mascot.meta';
import './Sprite.css';

export type { SpriteAnim };

export interface SpriteProps {
  anim: SpriteAnim;
  /** Integer pixel scale (1 sprite pixel = `scale` CSS pixels). */
  scale?: number;
  fps?: number;
  flip?: boolean;
  paused?: boolean;
  className?: string;
  style?: CSSProperties;
}

export default function Sprite({ anim, scale = 4, fps, flip = false, paused = false, className = '', style }: SpriteProps) {
  const { row, frames } = SPRITE_ANIMS[anim];
  const w = SPRITE_FRAME_W * scale;
  const h = SPRITE_FRAME_H * scale;
  const speed = fps ?? SPRITE_ANIMS[anim].fps;

  const css = {
    width: w,
    height: h,
    backgroundImage: `url(${sheetUrl})`,
    backgroundSize: `${SPRITE_COLS * w}px ${SPRITE_ROWS * h}px`,
    backgroundPositionY: -row * h,
    animationDuration: `${frames / speed}s`,
    animationTimingFunction: `steps(${frames})`,
    transform: flip ? 'scaleX(-1)' : undefined,
    '--sprite-end': `${-frames * w}px`,
    ...style,
  } as CSSProperties;

  return <div className={`sprite ${paused ? 'sprite--paused' : ''} ${className}`} style={css} aria-hidden="true" />;
}
